  1140   * g_utf8_casefold:
  1141   * @str: a UTF-8 encoded string
  1142   * @len: length of @str, in bytes, or -1 if @str is nul-terminated.
  1143   *
  1144   * Converts a string into a form that is independent of case. The
  1145   * result will not correspond to any particular case, but can be
  1146   * compared for equality or ordered with the results of calling
  1147   * g_utf8_casefold() on other strings.
  1148   *
  1149   * Note that calling g_utf8_casefold() followed by g_utf8_collate() is
  1150   * only an approximation to the correct linguistic case insensitive
  1151   * ordering, though it is a fairly good one. Getting this exactly
  1152   * right would require a more sophisticated collation function that
  1153   * takes case sensitivity into account. GLib does not currently
  1154   * provide such a function.
  1155   *
  1156   * Returns: a newly allocated string, that is a
  1157   *   case independent form of @str.
  1158   **/
  1159  gchar *
  1160  g_utf8_casefold (const gchar *str,
  1161                   gssize       len)
  1162  {
  1163    GString *result;
  1164    const char *p;
  1165
  1166    g_return_val_if_fail (str != NULL, NULL);
  1167
  1168    result = g_string_new (NULL);
  1169    p = str;
  1170    while ((len < 0 || p < str + len) && *p)
  1171      {
  1172        gunichar ch = g_utf8_get_char (p);
  1173
  1174        int start = 0;
  1175        int end = G_N_ELEMENTS (casefold_table);
  1176
  1177        if (ch >= casefold_table[start].ch &&
  1178            ch <= casefold_table[end - 1].ch)
  1179          {
  1180            while (TRUE)
  1181              {
  1182                int half = (start + end) / 2;
  1183                if (ch == casefold_table[half].ch)
  1184                  {
  1185                    g_string_append (result, casefold_table[half].data);
  1186                    goto next;
  1187                  }
  1188                else if (half == start)
  1189                  break;
  1190                else if (ch > casefold_table[half].ch)
  1191                  start = half;
  1192                else
  1193                  end = half;
  1194              }
